def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    # If the value has an isoformat method (e.g., datetime.time), use it.
    if hasattr(value, "isoformat"):
        try:
            return value.isoformat()
        except Exception:
