def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    # Define an __init__ that accepts the specified fields as positional or keyword arguments
    def __init__(self, *args, **kwargs):
        # Assign positional arguments to fields
        for i, field in enumerate(fields):
            if i < len(args):
                setattr(self, field, args[i])
            else:
                setattr(self, field, kwargs.get(field))
        # Optional srid attribute
        if 'srid' in kwargs:
            self.srid = kwargs['srid']

    # Prepare class attributes: default values for each field and the SRID map
    attrs = {field: None for field in fields}
    attrs['SRID_MAP'] = srid_map
    attrs['__init__'] = __init__

    # Create and return the new subclass of Point
    return type(name, (Point,), attrs)<|return|>

def deprecated(message):
