def extostr(cls, e, max_level=30, max_path_level=5):
    """Format an exception."""
    import traceback, os
    # Get the formatted exception lines with a limit on stack depth
    exc_lines = traceback.format_exception(type(e), e, e.__traceback__, limit=max_level)
    shortened = []
    for line in exc_lines:
        # Shorten file paths in the traceback lines
        if line.startswith('  File "'):
            start = line.find('"') + 1
            end = line.find('"', start)
            if end != -1:
                path = line[start:end]
                parts = path.split(os.sep)
                if len(parts) > max_path_level:
                    path = os.sep.join(parts[-max_path_level:])
                line = line[:start] + path + line[end:]
        shortened.append(line.rstrip('\n'))
    return '\n'.join(shortened)<|return|>

