def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for arg in sequence:
        # Expand tuples into individual elements
        if isinstance(arg, tuple):
            output.extend(arg)
        # Expand Declaration objects into their constituent interfaces/specs
        elif hasattr(arg, "interfaces"):
            output.extend(arg.interfaces)
        elif hasattr(arg, "implements"):
            output.extend(arg.implements)
        else:
            output.append(arg)
    return output<|return|>

