def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    errors = []

    # Helper to check string/bytes-like
    def _is_str_bytes(obj):
        return isinstance(obj, (str, bytes))

    for key, value in labels.items():
        # Validate key
        if not _is_str_bytes(key):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not LABEL_KEY_REGEX.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex"})

        # Validate value(s)
        if isinstance(value, list):
            for v in value:
                if not _is_str_bytes(v):
                    errors.append({f"['{v}']": 'expected string or bytes-like object'})
                else:
                    if not LABEL_VALUE_REGEX.match(v):
                        errors.append({f"['{v}']": f"Label value '{v}' does not match the regex"})
        else:
            if not _is_str_bytes(value):
                errors.append({str(key): 'expected string or bytes-like object'})
            else:
                if not LABEL_VALUE_REGEX.match(value):
                    errors.append({key: f"Label value '{value}' does not match the regex"})

    if errors:
        raise ValidationError(messages=errors)<|return|>

