def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Try to find a log attribute; common names are 'log' or 'validation_log'
    log = getattr(self, 'log', None)
    if log is None:
        log = getattr(self, 'validation_log', None)
    if not log:
        return ''
    lines = []
    # Handle different possible log structures
    if isinstance(log, dict):
        for key, value in log.items():
            lines.append(f"{prefix}{key}: {value}")
    elif isinstance(log, (list, tuple)):
        for item in log:
            if isinstance(item, tuple) and len(item) == 2:
                level, msg = item
                lines.append(f"{prefix}{level}: {msg}")
            else:
                lines.append(f"{prefix}{item}")
    else:
        # Fallback: just convert to string
        lines.append(f"{prefix}{log}")
    return "\n".join(lines)<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Determine the list of file entries
    if "file" in fixity:
        entries = [fixity["file"]]
    elif "files" in fixity:
        entries = fixity["files"]
        if not isinstance(entries, list):
            raise ValueError("'files' must be a list")
    else:
        raise ValueError("Fixity block must contain either a 'file' or 'files' key")

    seen = set()
    for entry in entries:
        if not isinstance(entry, dict):
            raise ValueError("Each file entry must be a dictionary")
        if "path" not in entry or "hash" not in entry:
            raise ValueError("Each file entry must contain 'path' and 'hash' keys")
        path = entry["path"]
        if path not in manifest_files:
            raise ValueError(f"File '{path}' referenced in fixity block not found in manifest")
        if path in seen:
            raise ValueError(f"Duplicate file entry for '{path}' in fixity block")
        seen.add(path)

    return True<|return|>

