    if hasattr(self, "__iter__") and not isinstance(self, (str, bytes)):
        for child in self:
            if hasattr(child, "pretty"):
                lines.append(child.pretty(indent + 2, debug))
            else:
                lines.append(f"{indent_str}  {repr(child)}")
    lines.append(f"{indent_str})")
