def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for e in args:
        # Only consider binary expressions
        if hasattr(e, 'op') and e.op in ('&', '|'):
            left, right = e.left, e.right

            # Helper to create new binary expression
            def make(op, a, b):
                return a & b if op == '&' else a | b

            # Absorption: A & (A | B) or (A | B) & A
            if e.op == '&':
                # left side pattern
                if hasattr(right, 'op') and right.op == '|':
                    if left == right.left or left == right.right:
                        new_args.append(left)
                        continue
                # right side pattern
                if hasattr(left, 'op') and left.op == '|':
                    if right == left.left or right == left.right:
                        new_args.append(right)
                        continue
                # Negative absorption: A & (~A | B) or (~A | B) & A
                if hasattr(right, 'op') and right.op == '|':
                    if hasattr(right.left, 'op') and right.left.op == '~' and right.left.operand == left:
                        new_args.append(make('&', left, right.right))
                        continue
                    if hasattr(right.right, 'op') and right.right.op == '~' and right.right.operand == left:
                        new_args.append(make('&', left, right.left))
                        continue

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if sys.version_info[0] < 3:
        def wrapper(*args, **kwargs):
            result = namefunc(*args, **kwargs)
            # In Python 2, unicode objects need to be encoded to bytes
            if isinstance(result, unicode):
                return result.encode('utf-8')
            return result
    else:
        def wrapper(*args, **kwargs):
            return namefunc(*args, **kwargs)
    return wrapper<|return|>

