def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    stack = [self]
    while stack:
        node = stack.pop()
        num_objects += 1
        valid = True
        if validate_objects:
            try:
                # Assume each node has a validate() method that returns a bool
                valid = node.validate()
            except Exception as exc:
                valid = False
                if show_warnings:
                    print(f"Validation error in {node!r}: {exc}")
        if check_digests and hasattr(node, "check_digest"):
            try:
                if not node.check_digest():
                    valid = False
                    if show_warnings:
                        print(f"Digest mismatch in {node!r}")
            except Exception as exc:
                valid = False
                if show_warnings:
                    print(f"Digest check error in {node!r}: {exc}")
        if valid:
            good_objects += 1
        # Add children to stack if the node is iterable
        try:
            for child in node:
                stack.append(child)
        except TypeError:
            # Node is not iterable; skip
            pass
    return num_objects, good_objects<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version.isdigit():
        raise ValueError("version must contain only digits")
    # Determine if the original version had leading zeros
    has_leading_zero = len(version) > 1 and version[0] == '0'
    # Compute the next numeric value
    next_num = int(version) + 1
    if has_leading_zero:
        # Preserve the original width
        width = len(version)
        return str(next_num).zfill(width)
    else:
        return str(next_num)<|return|>

