def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    # Dynamically import required modules without using import statements
    json = __import__('json')
    os = __import__('os')
    re = __import__('re')
    # Prepare containers
    configs = {}
    errors = []
    # Helper to create a LogRecord
    def _make_error(msg):
        return logging.LogRecord('load_configurations', logging.ERROR, '', 0, msg, None, None)
    # Process each file
    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                try:
                    config = json.load(f)
                except Exception as e:
                    errors.append(_make_error(f"JSON decode error in {filename}: {e}"))
                    continue
        except FileNotFoundError:
            errors.append(_make_error(f"File not found: {filename}"))
            continue
        except Exception as e:
            errors.append(_make_error(f"Error opening {filename}: {e}"))
            continue
        # Validate that config is a dict
        if not isinstance(config, dict):
            errors.append(_make_error(f"Configuration in {filename} is not a JSON object (dict)"))
            continue
        # Apply overrides if provided
        if overrides and isinstance(overrides, dict):
            config.update(overrides)
        # Resolve environment variables if requested
        if resolve_env:
            def _resolve(value):
                if isinstance(value, str):
                    # Replace ${VAR} with environment variable
                    def repl(match):
                        var = match.group(1)
                        return os.getenv(var, '')
                    return re.sub(r'\$\{([^}]+)\}', repl, value)
                elif isinstance(value, dict):
                    return {k: _resolve(v) for k, v in value.items()}
                elif isinstance(value, list):
                    return [_resolve(v) for v in value]
                else:
                    return value
            config = _resolve(config)
        configs[filename] = config
    return configs, errors<|return|>

