    return True<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Normalise base URL (remove trailing slash if present)
    base = url.rstrip('/')
    # Default document path if not supplied
    if document_path is None:
        document_path = '/.well-known/nodeinfo/2.0'
    # Ensure the document path starts with a slash
    if not document_path.startswith('/'):
        document_path = '/' + document_path
    # Build the full href
    href = f"{base}{document_path}"
    # Return the well‑known NodeInfo document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    if not document:
        raise ValueError("Empty webfinger document")

    # Try JSON first
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        pass

    # Fallback to XRD (XML) parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError as exc:
        raise ValueError("Invalid webfinger document: cannot parse XML") from exc

    ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}

    subject_elem = root.find('xrd:Subject', ns)
    subject = subject_elem.text if subject_elem is not None else None

    aliases = [a.text for a in root.findall('xrd:Alias', ns) if a.text]

    links = []
    for link in root.findall('xrd:Link', ns):
        # Convert attributes to a dict
        link_dict = {k: v for k, v in link.attrib.items()}
        # Some XRD implementations may include nested elements; capture them if present
        for child in link:
            tag = child.tag
            if tag.startswith('{'):
                # strip namespace
                tag = tag.split('}', 1)[1]
            link_dict[tag] = child.text
        links.append(link_dict)

    return {
        'subject': subject,
        'aliases': aliases,
        'links': links
    }<|return|>

