@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException('No spec content provided')

        # Load YAML if we received a string, otherwise assume a dict
        if isinstance(spec_content, str):
            try:
                # yaml module is expected to be available in the environment
                data = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f'Error parsing YAML: {exc}')
        elif isinstance(spec_content, dict):
            data = spec_content
        else:
            raise IRValidatorException('spec_content must be a string or a dict')

        if not isinstance(data, dict):
            raise IRValidatorException('Parsed spec content is not a dictionary')

        # Validate required fields if the class defines them
        required_fields = getattr(cls, 'REQUIRED_FIELDS', [])
        for field in required_fields:
            if field not in data:
                raise IRValidatorException(f'Missing required field: {field}')

        return data<|return|>

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise ValueError("yaml_file must be provided")

        try:
            with open(yaml_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except Exception as exc:
            raise IRValidatorException(
                f"Error loading YAML file '{yaml_file}': {exc}"
            ) from exc

        if not isinstance(data, dict):
            raise IRValidatorException(
                f"YAML file '{yaml_file}' does not contain a mapping at the top level"
            )

        required = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [field for field in required if field not in data]
        if missing:
            raise IRValidatorException(
                f"Missing required fields in YAML file '{yaml_file}': {', '.join(missing)}"
            )

        return data<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    include = parser_dict.get('include')
    if not include:
        return

    if not isinstance(include, dict):
        raise ValueError("The 'include' directive must be a dictionary of group definitions")

    # Ensure the groups container exists
    if not hasattr(self, 'groups'):
        self.groups = {}

    for name, group_def in include.items():
        # If the group already exists, merge dictionaries if possible
        if name in self.groups:
            existing = self.groups[name]
            if isinstance(existing, dict) and isinstance(group_def, dict):
                existing.update(group_def)
            else:
                self.groups[name] = group_def
        else:
            self.groups[name] = group_def
<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}

    # 1. Spec defaults (if the object has a spec attribute)
    spec = getattr(self, 'spec', None)
    if isinstance(spec, dict):
        defaults.update(spec.get('defaults', {}))

    # 2. Environment variables prefixed with SPEC_
    import os
    for key, val in os.environ.items():
        if key.startswith('SPEC_'):
            defaults[key[5:].lower()] = val

    # 3. Class-level defaults (if defined)
    cls_defaults = getattr(self.__class__, 'DEFAULTS', {})
    if isinstance(cls_defaults, dict):
        defaults.update(cls_defaults)

    return defaults<|return|>

