def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated = []
    # Collect deprecated arguments from both sources
    for arg_dict in (cli_args, answer_file_args):
        for key in arg_dict:
            # If the class defines a set of deprecated arguments, use it
            if hasattr(self, 'deprecated_args') and key in self.deprecated_args:
                deprecated.append(key)
            # Fallback: treat keys starting with 'old_' as deprecated
            elif key.startswith('old_'):
                deprecated.append(key)
    # Report any deprecated arguments found
    if deprecated:
        print("Deprecated arguments detected:", ', '.join(sorted(deprecated)))
    return deprecated<|return|>

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not hasattr(self, 'commands'):
        raise AttributeError("No commands defined")
    command = self.commands.get(command_name)
    if command is None:
        raise ValueError(f"Command '{command_name}' not found")
    spec = command.options.get(argument_name)
    if spec is None:
        raise ValueError(f"Option '{argument_name}' not found in command '{command_name}'")
    return spec<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        if 'required_when' not in opt:
            continue
        cond = opt['required_when']
        name = opt.get('name')
        if not name:
            continue
        try:
            if callable(cond):
                if cond(args):
                    required.append(name)
            elif isinstance(cond, str):
                # evaluate the condition string in a context that includes
                # the arguments and the command name
                local_ctx = dict(args)
                local_ctx['command_name'] = command_name
                if eval(cond, {}, local_ctx):
                    required.append(name)
        except Exception:
            # If the condition cannot be evaluated, ignore it
            pass
    return required<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Expect args to be a mapping of argument names to values
    for name, value in args.items():
        # Determine the maximum allowed length for this argument
        max_len = None
        if hasattr(self, 'max_lengths') and isinstance(self.max_lengths, dict):
            max_len = self.max_lengths.get(name)
        if max_len is None:
            attr_name = f'max_length_{name}'
            if hasattr(self, attr_name):
                max_len = getattr(self, attr_name)
        if max_len is None:
            # No length restriction defined for this argument
            continue
        # Only check if the value has a length
        try:
            length = len(value)
        except TypeError:
            continue
        if length > max_len:
            raise ValueError(
                f"Argument '{name}' length {length} exceeds maximum allowed {max_len}"
            )<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the mapping of allowed choices for this element
    choices_map = getattr(self, 'choices', {})
    if not isinstance(choices_map, dict):
        choices_map = {}

    # Determine how to iterate over the provided arguments
    if hasattr(args, 'items'):
        iterable = args.items()
    else:
        iterable = args

    for key, value in iterable:
        if key in choices_map:
            allowed = choices_map[key]
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{key}': {value}. "
                    f"Allowed values: {allowed}"
                )<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the instance defines min and max bounds
    if not hasattr(self, 'min') or not hasattr(self, 'max'):
        raise AttributeError("Instance must define 'min' and 'max' attributes for validation.")
    min_val = self.min
    max_val = self.max

    # Determine how to iterate over the arguments
    if isinstance(args, dict):
        iterable = args.items()
    else:
        iterable = enumerate(args)

    # Validate each argument value
    for key, value in iterable:
        if not (min_val <= value <= max_val):
            raise ValueError(f"Argument {key!r} value {value!r} out of bounds [{min_val!r}, {max_val!r}].")

    return True<|return|>

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        class ComplexArgumentType:
            def __init__(self, subcommand, type_name, option_name, spec_option):
                self.subcommand = subcommand
                self.type_name = type_name
                self.option_name = option_name
                self.spec_option = spec_option

            def __call__(self, value):
                # Basic parsing logic based on spec_option
                if isinstance(self.spec_option, dict):
                    # If a split character is defined, split the value
                    if 'split' in self.spec_option:
                        return value.split(self.spec_option['split'])
                    # If a set of allowed choices is defined, validate
                    if 'choices' in self.spec_option:
                        if value not in self.spec_option['choices']:
                            raise ValueError(
                                f"Invalid value '{value}' for option '{self.option_name}'. "
                                f"Allowed choices: {self.spec_option['choices']}"
                            )
                # Default: return the raw value
                return value

        return ComplexArgumentType(subcommand, type_name, option_name, spec_option)<|return|>

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    else:
        for item in extra_vars:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                vars_dict[item[0]] = item[1]
            else:
                raise ValueError("extra_vars must be a dict or iterable of key-value pairs")
    return vars_dict<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # If a type map is defined for this parser, use it
    type_map = getattr(self, "_arg_type_map", {}).get(parser_name, {})
    for key, val in list(values_dict.items()):
        # Use explicit type mapping if available
        if key in type_map:
            target_type = type_map[key]
            try:
                if target_type is bool:
                    if isinstance(val, str):
                        lower = val.lower()
                        if lower in ("true", "1", "yes", "on"):
                            values_dict[key] = True
                        elif lower in ("false", "0", "no", "off"):
                            values_dict[key] = False
                        else:
                            values_dict[key] = val
                    else:
                        values_dict[key] = bool(val)
                else:
                    values_dict[key] = target_type(val)
            except Exception:
                # If conversion fails, keep original
                values_dict[key] = val
            continue

        # Heuristic conversion for common types
        if isinstance(val, str):
            # Try integer
            try:
                values_dict[key] = int(val)
                continue
            except ValueError:
                pass
            # Try float
            try:
                values_dict[key] = float(val)
                continue
            except ValueError:
                pass
            # Try boolean
            lower = val.lower()
            if lower in ("true", "1", "yes", "on"):
                values_dict[key] = True
                continue
            if lower in ("false", "0", "no", "off"):
                values_dict[key] = False
                continue
            # Try comma‑separated list
            if "," in val:
                values_dict[key] = [v.strip() for v in val.split(",")]
                continue
        # Leave value unchanged if no conversion applied
    # No explicit return needed; values_dict is modified in place.<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Find the plugin spec file (JSON or YAML)
    spec_path = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_path = path
            break
    if not spec_path:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load the spec
    if spec_path.endswith(".json"):
        with open(spec_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    else:
        import yaml
        with open(spec_path, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(data)<|return|>

